<script lang="ts">
	import { replaceState } from "$app/navigation";
	import { page } from "$app/state";
	import { API, Constants } from "$lib";
	import ErrorComponent from "$lib/components/ErrorComponent.svelte";
	import * as Empty from "$lib/components/ui/empty";
	import { StatusCodes } from "http-status-codes";
	import { onDestroy, onMount } from "svelte";
	import { nativeAuthority } from "$platform/mutation-authority";
	import { Skeleton } from "../ui/skeleton";
	import Entry from "./comments-entry.svelte";
	import { useComments } from "./context.svelte";

	const comments = useComments();
	let isMounted = $state(false);
	let error = $state<Constants.Error.Error>();

	let feedGeneration = 0, feedDisposed = false;
	onDestroy(() => { feedDisposed = true; feedGeneration++; });
	$effect(() => {
		const threadId = comments.thread.id, href = page.url.href, authority = $nativeAuthority;
		const generation = ++feedGeneration;
		comments.feed = undefined; error = undefined; isMounted = false;
		const alive = () => !feedDisposed && generation === feedGeneration && comments.thread.id === threadId && page.url.href === href && $nativeAuthority === authority;
		const q = new URLSearchParams();
		const targetPage = page.url.searchParams.get("page"); if (Number(targetPage) > 1) q.set("page", targetPage!);
		if (page.url.searchParams.get("sort") === "oldest") q.set("order", "asc");
		void API.Thread.Replies(threadId, q).then(res => {
			if (!alive()) return;
			if (res?.status === StatusCodes.OK && res.body) { res.body.data ??= []; comments.feed = res.body; }
			else throw res?.status === StatusCodes.TOO_MANY_REQUESTS ? Constants.Error.TooManyRequests : Constants.Error.Unknown;
		}).catch(cause => { if (alive()) error = cause instanceof Constants.Error.Error ? cause : Constants.Error.Unknown; }).finally(() => { if (alive()) isMounted = true; });
	});
</script>

{#if error}
	<ErrorComponent {error} />
{:else if isMounted && comments.feed}
	{#if comments.feed.data?.length}
		<div class="space-y-2">
			{#each comments.feed.data as reply, i (reply)}
				<Entry bind:reply={comments.feed!.data![i]} />
			{/each}
		</div>
	{:else}
		<Empty.Root>
			<Empty.Header>
				<Empty.Title>No results found</Empty.Title>
				<Empty.Description>Be the first to comment and share your thoughts!</Empty.Description>
			</Empty.Header>
		</Empty.Root>
	{/if}
{:else}
	<div class="space-y-2">
		{#each Array.from({ length: 20 }) as _}
			<Skeleton class="bg-card h-55" />
		{/each}
	</div>
{/if}
